  render: () => <Frame>
      <RSHighcharts containerProps={{
      style: {
        height: '100%',
        width: '100%'
      }
    }} options={{
      chart: {
        type: 'column'
      },
      title: {
        text: 'Open risks by severity'
      },
      xAxis: {
        categories: ['Critical', 'High', 'Medium', 'Low']
      },
      yAxis: {
        title: {
          text: 'Count'
        }
      },
      legend: {
        enabled: false
      },
      series: [{
        type: 'column',
        name: 'Open risks',
        data: [{
          y: 8,
          color: '#CE1B1B'
        }, {
          y: 14,
          color: '#E37373'
        }, {
          y: 17,
          color: '#F2A041'
        }, {
          y: 8,
          color: '#8CC862'
        }]
      } as any]
    }} />
    </Frame>
